package com.wizzadrds.theworldremembers.dream; import com.wizzadrds.theworldremembers.memory.*; import com.wizzadrds.theworldremembers.stress.NpcStressManager; import java.util.*; public final class DreamGenerator{private DreamGenerator(){} public static Optional<Dream> generate(UUID sleeper,List<Memory> memories,int stress,long tick){if(memories.isEmpty())return Optional.empty(); long seed=sleeper.getMostSignificantBits()^sleeper.getLeastSignificantBits()^tick/24000; var rnd=new Random(seed); List<Memory> ordered=memories.stream().sorted(Comparator.comparing(Memory::gameTime)).toList(); Memory source=ordered.get(rnd.nextInt(ordered.size())); DreamType type=stress>=60?DreamType.FEAR:(source.importance().ordinal()>=MemoryImportance.HISTORICAL.ordinal()?DreamType.NOSTALGIA:(source.type()==MemoryEventType.NPC_DIED||source.type()==MemoryEventType.NPC_FAMILY_LOST?DreamType.FEAR:(rnd.nextBoolean()?DreamType.MEMORY:DreamType.IMPOSSIBLE))); boolean factual=type!=DreamType.IMPOSSIBLE; String motif=switch(type){case MEMORY->"memory:"+source.type().name();case FEAR->"fear:"+source.type().name();case NOSTALGIA->"nostalgia:"+source.type().name();case IMPOSSIBLE->"impossible:"+source.type().name();}; return Optional.of(new Dream(sleeper,type,tick,motif,source.gameTime(),factual));}}
